"""Evaluate whether declared source dependencies changed."""

import json
from typing import Any, Dict, Mapping


_MISSING = {"kind": "missing"}


def _canonical_json(value: Any) -> str:
    """Return a deterministic, type-preserving representation of JSON data."""
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def evaluate(request: Mapping[str, Any], policy: Mapping[str, Any]) -> Dict[str, Any]:
    """Return review status for relevant, uniquely declared source paths.

    Missing mapping entries are treated as the canonical missing state. Inputs are
    only read and are never normalized or modified in place.
    """
    ignored = set(policy.get("ignored", []))
    saved = request.get("saved", {})
    current = request.get("current", {})

    paths = {path for path in request.get("declared", []) if path not in ignored}
    changed = sorted(
        path
        for path in paths
        if _canonical_json(saved.get(path, _MISSING))
        != _canonical_json(current.get(path, _MISSING))
    )

    return {"needs_review": bool(changed), "changed": changed}
